    # твой код: total + цикл
    pass

solution:
def sum_positive(nums):
    total = 0
    for n in nums:
        if n > 0:
            total += n
    return total

def flatten_once(matrix):
    result = []
    for row in matrix:
        result.extend(row)
    return result

