def word_frequency(text):
    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts

def is_palindrome(text):
    clean = ''.join(char.lower() for char in text if char.isalnum())
    return clean == clean[::-1]

