solution:
def chunk_list(items, size):
    if size <= 0:
        return []
    return [items[i:i + size] for i in range(0, len(items), size)]

starter_code:
def normalize_scores(scores):
    # твой код: ручной поиск low/high, затем формула
    pass

solution:
def normalize_scores(scores):
    if not scores:
        return []

    low = scores[0]
    high = scores[0]
    for score in scores:
        if score < low:
            low = score
        if score > high:
            high = score

    if high == low:
        return [0.0 for _ in scores]

    result = []
    for score in scores:
        result.append((score - low) / (high - low))
    return result

